interface ActionAgentInteractionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    popupEntryId?: string
    runtime: ActionPopupRuntime
}

/** Agent interaction surface, including agent children started by command actions. */
export function ActionAgentInteraction(props: ActionAgentInteractionProps) {
    const { action, assignmentContext, popupEntryId, runtime } = props
    const {
        bindingStore, conversationStore, historyStore, inputStore, resultStore, runValidationError, scheduleStore,
        settingsStore, usageValuesService,
    } = runtime
    const boundRunId = useBoundRunId(bindingStore)
    const activeActionType = useRunSelector(boundRunId, (run) => run?.activeActionType ?? null)
    const visible = action.type === 'agent' || activeActionType === 'agent'
    const displayedUsageValuesService = action.type === 'agent'
        && assignmentContext.kind === 'card'
        && !!assignmentContext.file
        && !!assignmentContext.cardInternalId
        ? usageValuesService
        : undefined

    return (
        <Stack sx={{ display: visible ? 'contents' : 'none' }}>
            <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                <ActionLogErrorOwner bindingStore={bindingStore} resultStore={resultStore} />
                <ActionConversationChat
                    actionId={action.id}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    store={conversationStore}
                    usageValuesService={displayedUsageValuesService}
                />
                <ActionAgentPromptOwner
                    action={action}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    settingsStore={settingsStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                />
                <ActionAgentApprovals bindingStore={bindingStore} />
                <ActionAgentQuestionOwner bindingStore={bindingStore} />
            </Stack>
        </Stack>
    )
}

import { applicationStorage } from '../services/storage/application_storage'

export const RECENT_LOCAL_REPOSITORIES_STORAGE_KEY = 'md2.recentLocalRepositories'
export const MAX_RECENT_LOCAL_REPOSITORIES = 5

function isRecentRepositoryList(value: unknown): value is string[] {
    return Array.isArray(value) && value.every((path) => typeof path === 'string' && path.length > 0)
}

/** Read canonical local repository roots, newest first. */
export function readRecentLocalRepositories() {
    const storedValue = applicationStorage.getItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY)
    if (!storedValue) return []

    try {
        const parsedValue: unknown = JSON.parse(storedValue)
        if (isRecentRepositoryList(parsedValue)) return parsedValue.slice(0, MAX_RECENT_LOCAL_REPOSITORIES)
    } catch {
        // Invalid stored history is discarded below.
    }

    applicationStorage.removeItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY)

    return []
}

/** Record one successfully opened canonical root with Windows case-insensitive uniqueness. */
export async function recordRecentLocalRepository(rootPath: string) {
    if (rootPath.length === 0) throw new Error('Local repository root path is required')

    const storedValue = await applicationStorage.readCurrentItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY)
    let currentRepositories: string[] = []
    if (storedValue) {
        try {
            const parsedValue: unknown = JSON.parse(storedValue)
            if (isRecentRepositoryList(parsedValue)) currentRepositories = parsedValue.slice(0, MAX_RECENT_LOCAL_REPOSITORIES)
        } catch {
            // Invalid stored history is replaced below.
        }
    }
    const normalizedRoot = rootPath.toLowerCase()
    const recentRepositories = currentRepositories
        .filter((path) => path.toLowerCase() !== normalizedRoot)
    const nextRepositories = [rootPath, ...recentRepositories].slice(0, MAX_RECENT_LOCAL_REPOSITORIES)
    await applicationStorage.writeCurrentItem(RECENT_LOCAL_REPOSITORIES_STORAGE_KEY, JSON.stringify(nextRepositories))

    return nextRepositories
}

